import{_ as e,o as p,c as l,ae as r}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"考拉记账会员服务协议","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh/legal/membership.md","filePath":"v1/zh/legal/membership.md"}'),i={name:"v1/zh/legal/membership.md"};function t(h,a,o,n,d,s){return p(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="考拉记账会员服务协议" tabindex="-1">考拉记账会员服务协议 <a class="header-anchor" href="#考拉记账会员服务协议" aria-label="Permalink to &quot;考拉记账会员服务协议&quot;">​</a></h1><p>更新日期：2026年05月03日</p><p>生效日期：2026年05月03日</p><p>提示条款</p><p>为维护您的合法权益，请您在开通或使用“考拉记账会员服务”（以下简称“会员服务”）前，务必审慎阅读并充分理解本协议全部条款，尤其是免除或限制责任、自动续费、退订与退款、争议解决等条款。</p><p>【签约动作】您点击同意本协议并开通/续费会员服务，或以其他任何方式实际使用会员服务的，均视为您已阅读、理解并同意接受本协议的全部内容，本协议即对您与“考拉记账”产生法律约束力。</p><p>【重要说明】本协议为通用文本，可能因法律法规、平台规则（如 Apple App Store）及产品形态变化而调整。若您不同意本协议或其后续更新，请立即停止开通或使用会员服务。</p><hr><h2 id="_1-定义与主体" tabindex="-1">1. 定义与主体 <a class="header-anchor" href="#_1-定义与主体" aria-label="Permalink to &quot;1. 定义与主体&quot;">​</a></h2><p>1.1 “考拉记账”或“本应用”：指由个人开发者运营的记账应用及其相关服务。</p><p>1.2 “开发者/运营者”：指提供并运营本应用及会员服务的个人开发者（以下简称“开发者”）。</p><p>1.3 “您/用户”：指下载、安装、注册/登录并使用本应用及会员服务的自然人。</p><p>1.4 “会员/会员用户”：指在有效期内已通过平台支持的付费方式成功开通会员服务并可享受相应权益的用户。</p><p>1.5 “平台”：指您开通会员服务所使用的第三方应用分发及支付平台（例如 Apple App Store）。涉及扣费、退款、发票/收据等事项时，应同时遵守平台规则。</p><h2 id="_2-协议的范围与变更" tabindex="-1">2. 协议的范围与变更 <a class="header-anchor" href="#_2-协议的范围与变更" aria-label="Permalink to &quot;2. 协议的范围与变更&quot;">​</a></h2><p>2.1 本协议是您与开发者之间关于您开通并使用会员服务所订立的协议，与本应用《用户协议》《隐私政策》共同构成完整协议体系。本协议与其他协议不一致的，以本协议为准；未约定事项，以相关协议及平台规则为准。</p><p>2.2 开发者有权根据法律法规、监管要求、平台规则、业务调整等对本协议进行更新。更新后的协议将在本应用内或相关页面展示并自公示之日起生效。若您在更新后继续使用会员服务，视为您接受更新后的协议；若您不同意，应立即停止使用会员服务并按平台规则取消订阅。</p><h2 id="_3-会员服务内容" tabindex="-1">3. 会员服务内容 <a class="header-anchor" href="#_3-会员服务内容" aria-label="Permalink to &quot;3. 会员服务内容&quot;">​</a></h2><p>3.1 会员服务为数字化服务，主要用于解锁或提升本应用内部分功能体验。会员权益以本应用内“会员/解锁会员”页面展示为准，可能包括但不限于：</p><ul><li>快捷记账相关能力</li><li>多账本功能</li><li>云同步能力</li><li>多币种支持</li><li>账单导出能力</li><li>拆分账单能力</li><li>报销相关能力</li></ul><p>3.2 会员服务不等同于金融、理财、税务、审计或会计专业服务。本应用提供的统计、报表、汇率换算、导出等功能仅为工具性辅助，开发者不对其适用性、完整性、及时性作保证。</p><p>3.3 会员权益可能因产品迭代而调整（新增、变更、下线或条件变化）。开发者将以适当方式对重大变更进行提示。您理解并同意上述调整不必然构成违约或退款事由。</p><h2 id="_4-开通方式、周期与费用" tabindex="-1">4. 开通方式、周期与费用 <a class="header-anchor" href="#_4-开通方式、周期与费用" aria-label="Permalink to &quot;4. 开通方式、周期与费用&quot;">​</a></h2><p>4.1 您可通过本应用内提供的购买入口开通会员服务。当前会员周期可能包含“按月/按年”等选项，具体以购买页展示为准。</p><p>4.2 会员服务的价格由平台展示并以平台实际扣费金额为准。不同地区、不同币种、不同税费规则下价格可能不同。</p><p>4.3 开通会员服务后，权益即时生效（以平台回调确认成功为准）。会员有效期以平台订单/订阅状态为准。</p><p>4.4 如您更换设备或重装应用，可在登录同一平台账号及满足平台规则的前提下，通过“恢复购买”等方式恢复会员权益。</p><h2 id="_5-自动续费-订阅-规则" tabindex="-1">5. 自动续费（订阅）规则 <a class="header-anchor" href="#_5-自动续费-订阅-规则" aria-label="Permalink to &quot;5. 自动续费（订阅）规则&quot;">​</a></h2><p>5.1 若您开通的是自动续费会员（订阅），则在每个计费周期到期前，平台将依据您的订阅状态自动扣费并延长会员有效期。扣费时间、扣费方式、续费失败处理等以平台规则为准。</p><p>5.2 您可在平台的订阅管理中取消自动续费。取消后，您仍可在当前已付费周期内继续享受会员权益，已付费周期届满后不再续费。</p><p>5.3 自动续费的取消路径通常为：Apple 设备“设置 → Apple ID → 订阅”中取消（具体以系统版本为准）。本应用内提供的“管理订阅”等入口仅为便捷跳转，不改变平台的最终处理结果。</p><h2 id="_6-退订与退款" tabindex="-1">6. 退订与退款 <a class="header-anchor" href="#_6-退订与退款" aria-label="Permalink to &quot;6. 退订与退款&quot;">​</a></h2><p>6.1 会员服务属于数字内容/数字服务。除法律法规另有规定外，是否支持退款以及退款金额、到账时间等由平台规则决定。开发者无法绕过平台直接为您退订或退款。</p><p>6.2 若您认为存在异常扣费、重复扣费、未到账等情况，建议您优先在平台订单中查看订阅状态并按平台流程申请退款/申诉；同时，您可通过本协议第 12 条所载联系方式联系开发者协助排查。</p><p>6.3 因您主动取消、未及时取消导致自动续费扣费、误操作购买等情形产生的后果，通常应由您自行承担（以平台规则及适用法律为准）。</p><h2 id="_7-使用规范与限制" tabindex="-1">7. 使用规范与限制 <a class="header-anchor" href="#_7-使用规范与限制" aria-label="Permalink to &quot;7. 使用规范与限制&quot;">​</a></h2><p>7.1 会员服务仅限您本人在合理范围内的个人用途使用，不得以任何形式转让、赠与、出租、出借、售卖或用于商业化对外提供服务。</p><p>7.2 您不得通过破解、反编译、篡改客户端、利用漏洞、自动化脚本、恶意刷单等不正当方式获取或使用会员权益。</p><p>7.3 若您违反本协议或相关法律法规、平台规则，开发者有权在不事先通知的情况下采取包括但不限于限制功能、暂停服务、终止会员权益等措施；若因此造成损失，由您自行承担。</p><h2 id="_8-服务中断、变更与终止" tabindex="-1">8. 服务中断、变更与终止 <a class="header-anchor" href="#_8-服务中断、变更与终止" aria-label="Permalink to &quot;8. 服务中断、变更与终止&quot;">​</a></h2><p>8.1 开发者将尽力保障会员服务的连续性与稳定性，但因以下原因导致服务中断、延迟、异常或部分不可用的，开发者不承担违约责任：</p><ul><li>系统维护、升级、故障修复、机房/网络/第三方服务（含云服务、推送、支付平台等）故障</li><li>不可抗力或政府行为</li><li>您的设备、系统版本、网络环境、权限设置等原因</li></ul><p>8.2 开发者有权基于安全、合规、产品调整等原因对会员服务进行变更或终止。若因终止导致您无法继续使用会员服务，开发者将尽力在合理范围内提供必要提示；涉及费用结算/退款的，仍以平台规则及适用法律为准。</p><h2 id="_9-数据与云同步特别说明" tabindex="-1">9. 数据与云同步特别说明 <a class="header-anchor" href="#_9-数据与云同步特别说明" aria-label="Permalink to &quot;9. 数据与云同步特别说明&quot;">​</a></h2><p>9.1 若会员权益包含云同步功能，云同步服务的实现可能依赖第三方能力与网络环境。开发者将尽力保障同步功能可用，但不对同步的实时性、完整性、无误差作绝对承诺。</p><p>9.2 建议您定期备份重要数据。对于因设备丢失、误删、网络故障、同步冲突、第三方服务异常等导致的数据丢失或不一致，开发者在法律允许范围内不承担责任。</p><h2 id="_10-知识产权" tabindex="-1">10. 知识产权 <a class="header-anchor" href="#_10-知识产权" aria-label="Permalink to &quot;10. 知识产权&quot;">​</a></h2><p>10.1 本应用及其相关内容（包括但不限于程序、界面、图标、商标、文本、算法、数据结构等）均受法律保护，相关权利归开发者或合法权利人所有。</p><p>10.2 未经授权，您不得以任何方式复制、修改、传播、出租、销售或用于其他侵权用途。</p><h2 id="_11-免责声明与责任限制" tabindex="-1">11. 免责声明与责任限制 <a class="header-anchor" href="#_11-免责声明与责任限制" aria-label="Permalink to &quot;11. 免责声明与责任限制&quot;">​</a></h2><p>11.1 在法律允许的最大范围内，开发者不对因使用或无法使用会员服务所产生的间接损失、可得利益损失、数据损失等承担责任。</p><p>11.2 若开发者因本协议项下向您承担责任的，在法律允许范围内，开发者的责任总额以您就该争议所涉会员服务在最近一个计费周期内实际支付的金额为上限（如适用法律另有规定的，从其规定）。</p><h2 id="_12-联系方式" tabindex="-1">12. 联系方式 <a class="header-anchor" href="#_12-联系方式" aria-label="Permalink to &quot;12. 联系方式&quot;">​</a></h2><p>如您对会员服务、订阅、恢复购买、权益异常等有疑问，可通过以下方式联系开发者：</p><ul><li>电子邮箱：ruanweidev@163.com</li></ul><h2 id="_13-法律适用与争议解决" tabindex="-1">13. 法律适用与争议解决 <a class="header-anchor" href="#_13-法律适用与争议解决" aria-label="Permalink to &quot;13. 法律适用与争议解决&quot;">​</a></h2><p>13.1 本协议的订立、生效、履行、解释及争议解决适用中华人民共和国法律（不含冲突规范）。</p><p>13.2 因本协议产生的或与本协议有关的争议，双方应先友好协商解决；协商不成的，任一方可向开发者所在地有管辖权的人民法院提起诉讼。</p><h2 id="_14-其他" tabindex="-1">14. 其他 <a class="header-anchor" href="#_14-其他" aria-label="Permalink to &quot;14. 其他&quot;">​</a></h2><p>14.1 本协议部分条款无效不影响其他条款的效力。</p><p>14.2 本协议标题仅为阅读便利，不影响条款含义解释。</p><p>14.3 若本协议与平台规则存在冲突，涉及支付、续费、退款、订阅状态认定等事项以平台规则为准；其余事项以本协议为准。</p>',62)])])}const u=e(i,[["render",t]]);export{c as __pageData,u as default};
